values (
  (select id from public.tour_categories where slug = 'culture-history'),
  (select id from public.destinations where slug = 'stone-town'),
  'Spice Farm Tour', 'spice-farm-tour', 'See, smell and taste the spices that made Zanzibar the ''Spice Island''.', 'Visit a working spice farm outside Stone Town. A local guide shows you cloves, nutmeg, cinnamon, vanilla and other plants, and explains how they are grown and used.

Many visits include tasting seasonal tropical fruit and an optional local lunch.', 'Half day (approx. 3–4 hours)',
  'half_day', array['family', 'cultural']::text[], array['Guided walk through a spice farm', 'Seasonal fruit tasting', 'Optional Swahili lunch']::text[], array['Return transfer from Stone Town', 'Farm guide']::text[], array['Personal expenses and tips', 'Drinks unless stated', 'Travel insurance', 'Lunch (optional extra)']::text[], array['Comfortable shoes', 'Insect repellent', 'Cash for optional spice purchases']::text[],
  'Hotel pickup in or near Stone Town. Exact time confirmed on booking.', 'easy', 'Suitable for all ages.',
  '[{"title":"Drive out of town","description":"Transfer from Stone Town to a working spice farm in the countryside."},{"title":"Guided farm walk","description":"See, smell and taste cloves, nutmeg, cinnamon, vanilla, pepper and more."},{"title":"Fruit tasting","description":"Try seasonal tropical fruits grown on the farm."},{"title":"Optional lunch","description":"Enjoy a Swahili meal cooked with local spices (optional extra)."},{"title":"Return","description":"Transfer back to your accommodation."}]'::jsonb, array['Spices and fruits on show vary with the season.', 'Farm paths can be muddy after rain — wear closed shoes.', 'Spices and oils are usually available to buy; bring some cash.']::text[], '[{"question":"Is it suitable for children?","answer":"Yes — it''s a gentle walk and children usually enjoy guessing the spices."},{"question":"Can it be combined with Stone Town?","answer":"Yes, it''s a popular half-day pairing with the Stone Town City Tour."}]'::jsonb, 'Two women wearing woven leaf crowns hold fresh coconuts while taking a photo',
  false, 'published', 'Spice Farm Tour', 'Guided spice farm visit near Stone Town.', true, 2);
