  '[{"title":"Board at the waterfront","description":"Meet the crew on the Stone Town waterfront in the late afternoon."},{"title":"Sail the coast","description":"Sail gently along the coast as the light turns golden."},{"title":"Sunset","description":"Watch the sun set over the Indian Ocean with light refreshments."},{"title":"Return","description":"Back on shore shortly after sunset."}]'::jsonb, array['Sailing depends on wind and weather.', 'A light jacket is useful once the sun goes down.']::text[], '[{"question":"Is it good for couples and groups?","answer":"Yes — it''s a popular choice for couples, families and small groups."}]'::jsonb, 'Two dhows sailing on the sea at sunset',
